{
  "title": "CSCI-101: Principles of Computing – Foundations Companion",
  "learningObjectives": [
    "Students will articulate the core components of a computational problem (statement, input/output, algorithm) using precise terminology from the course",
    "Students will implement a basic solution in Python by applying lexical analysis, namespaces, and exception handling as described in the language",
    "Students will evaluate the correctness of their code through tracing, boundary testing, and debugging, aligning with the course's emphasis on written/"
  ],
  "beats": [
    {
      "title": "Defining the Computational Problem",
      "claim": "Programming begins with precise problem statements, input and output examples, and algorithms written independently of syntax.",
      "example": "Given a list of integers, the problem statement asks to return the sum of all positive values; inputs are [1, -2, 3] and outputs are 4.",
      "visualDirection": "Display a three-column table labeled 'Problem Statement', 'Input Example', and 'Output Example' with the listed content.",
      "sourceIds": ["opendsa-programming-foundations", "rit-csci-101"]
    },
    {
      "title": "Variables, Expressions, and Control",
      "claim": "Variables represent values and state, expressions compute values, and control structures select or repeat operations.",
      "example": "In Python, x = 5 is a variable assignment; x + 3 is an expression; if x > 0: print('positive') is a control structure.",
      "visualDirection": "Show a code snippet with three highlighted lines: the variable declaration, the arithmetic expression, and the conditional statement.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Functions and Decomposition",
      "claim": "Functions decompose a solution into named operations with parameters and results.",
      "example": "def sum_positive(nums): total = 0; for n in nums: if n > 0: total += n; return total",
      "visualDirection": "Render a function definition block with the name 'sum_positive' and its body, using syntax highlighting for the loop and conditional.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Recursion and Base Cases",
      "claim": "Recursion solves a problem through smaller instances and requires a base case.",
      "example": "def factorial(n): if n == 0: return 1; else: return n * factorial(n-1)",
      "visualDirection": "Illustrate a call stack diagram showing factorial(3) expanding to factorial(2), factorial(1), and the base case factorial(0).",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Data Structures: Lists, Stacks, Queues",
      "claim": "Lists represent ordered sequences, stacks use last-in first-out access, queues use first-in first-out access.",
      "example": "A list [1,2,3] can be pushed onto a stack; popping yields 3, then 2, then 1; a queue would yield 1, 2, 3.",
      "visualDirection": "Draw three separate boxes labeled 'List', 'Stack', and 'Queue' with arrows indicating push/pop or enqueue/dequeue operations.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Trees and Graphs",
      "claim": "Trees represent hierarchy, and graphs represent connected entities.",
      "example": "A family tree is a tree; a social network where people are nodes and friendships are edges is a graph.",
      "visualDirection": "Show a simple binary tree diagram and a small undirected graph with four nodes and three edges.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Searching and Sorting",
      "claim": "Searching and sorting algorithms depend on representation and invariants.",
      "example": "Binary search requires a sorted list; insertion sort maintains the invariant that the left portion is always sorted.",
      "visualDirection": "Animate a binary search on a sorted array and an insertion sort step-by-step, highlighting the invariant after each iteration.",
      "sourceIds": ["opendsa-programming-foundations"]
    },
    {
      "title": "Correctness, Tests, and Debugging",
      "claim": "Correctness arguments, tests, tracing, and debugging compare intended behavior with observable results, including boundary and error cases.",
      "example": "Test sum_positive with empty list, all negatives, and large numbers; trace variable values to find a logical error.",
      "visualDirection": "Present a table of test cases (input, expected output, actual output) and a trace log showing variable states for one failing case.",
      "sourceIds": ["opendsa-programming-foundations", "python-language-reference"]
    },
    {
      "title": "Python Language Mechanics",
      "claim": "Python objects have identity, a type, and a value; names are bound to objects within namespaces and scopes; exceptions interrupt normal control flow.",
      "example": "a = [1]; b = a; a.append(2); print(b) outputs [1,2] because a and b share identity; try/except handles division errors.",
      "visualDirection": "Show a diagram of a namespace containing two names 'a' and 'b' pointing to the same list object, and a flowchart of an exception being raised and caught.",
      "sourceIds": ["python-language-reference"]
    },
    {
      "title": "Course Workflow and Communication",
      "claim": "Students will develop step-by-step written solutions, implement them in a programming language, and demonstrate oral and written communication through papers, discussions, and term",
      "example": "A student writes a pseudocode solution, translates it to Python, submits a short paper explaining the approach, and presents it in a group debate.",
      "visualDirection": "Create a timeline graphic with four milestones: 'Written Solution', 'Implementation', 'Short Paper', 'Oral Presentation', each linked to the relevant course activities.",
      "sourceIds": ["rit-csci-101"]
    }
  ]
}
